function accountMatches(p,q){const term=norm(q);if(!term)return true;const ix=indexData(),id=String(p.partyId||p.id||'').replace(/^party:/,'');if((ix.partyNotes.get(id)||'').includes(term)||(ix.expenseNotes.get(p.account||p.name)||'').includes(term))return true;const digits=String(q).replace(/\D/g,'');return norm([p.name,p.phone,p.details,p.note,p.notes].filter(Boolean).join(' ')).includes(term)||(!!digits&&(p.phone||'').replace(/\D/g,'').includes(digits))}
