function countSheet(kind,label,d){const c=closings().find(c=>c.date===date),prev=closings().find(c=>c.date===yesterday(date)),locked=kind==='opening'&&prev?.change!=null,source=locked?prev:c,field=locked?'change':kind;const rows=source?.[field+'Rows']|| (source?.[field]!=null?[source[field]]:[]);return `<form data-count="${kind}"><small>${locked?'Pichhle din se auto':label+' ki ginti'}</small><div class="count-rows">${(rows.length?rows:['']).map(n=>`<input name="count" type="number" min="0" step="0.01" inputmode="decimal" placeholder="Raqam Rs" aria-label="${label} raqam" value="${n===''?'':n/100}" ${locked||(!owner()&&date!==today())?'readonly':''}>`).join('')}</div>${!locked&&(owner()||date===today())?'<button type="button" data-count-add>＋ Nayi raqam / Row</button><button type="submit">Save ginti</button>':''}<small>Jama: <b data-count-total>${money(d[kind])}</b></small></form>`}
function setupCounts(){document.querySelectorAll('[data-count]').forEach(f=>{const kind=f.dataset.count,key=date+':count:'+kind;const draft=sheetDrafts.get(key);if(draft&&f.querySelector('[type=submit]'))f.querySelector('.count-rows').innerHTML=draft.map(v=>`<input name="count" type="number" min="0" step="0.01" inputmode="decimal" placeholder="Raqam Rs" aria-label="${kind} raqam" value="${esc(v)}">`).join('');const values=()=>[...f.querySelectorAll('[name=count]')].map(i=>i.value);const update=()=>{sheetDrafts.set(key,values());try{f.querySelector('[data-count-total]').textContent=money(values().reduce((n,v)=>n+cents(v),0))}catch{}};f.oninput=update;const add=f.querySelector('[data-count-add]');if(add)add.onclick=()=>{const input=f.querySelector('[name=count]').cloneNode();input.value='';f.querySelector('.count-rows').append(input);update();input.focus()};f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('[type=submit]');if(!b)return;b.disabled=true;try{const rows=values().filter(v=>v.trim()!=='').map(cents);if(!rows.length)throw Error('Ginti likhein; zero ho to 0 likhein');const c=closings().find(c=>c.date===date);if(kind==='opening'&&closings().some(c=>c.date===yesterday(date)&&c.change!=null))throw Error('Kal ka Change pichhle din se aa raha hai');await save({...c,type:'closing',id:'closing-'+date,date,[kind]:rows.reduce((a,b)=>a+b,0),[kind+'Rows']:rows},c);sheetDrafts.delete(key);render()}catch(e){error(e)}finally{b.disabled=false}}})}
