restoreFile.onchange=async e=>{const ticket=++restoreRead;restoreDraft=null;restoreButton.disabled=true;const f=e.target.files[0];if(!f){restorePreview.textContent='Pehle JSON backup choose karein.';return}restorePreview.textContent='Backup parh rahe hain…';try{const data=JSON.parse(await f.text());if(ticket!==restoreRead||!restoreFile.isConnected)return;if(data.format!=='sam-blue-khata-v1'||!Array.isArray(data.records))throw Error('Sam Khata ki JSON backup file choose karein.');if(!data.records.length)throw Error('Is backup mein koi record nahi.');if(data.records.some(r=>!r||typeof r.id!=='string'||typeof r.type!=='string'))throw Error('Backup ke records durust nahi.');restoreDraft=data.records;const accounts=data.records.filter(r=>r.type==='party'&&!r.deleted).length,entries=data.records.filter(r=>r.type==='entry'&&!r.deleted).length;restorePreview.textContent=f.name+' · '+accounts+' accounts · '+entries+' entries · Total '+data.records.length+' records. Ab Restore / Save Backup dabayein.';restoreButton.disabled=false}catch(e){if(ticket===restoreRead){restorePreview.textContent=e.message;restoreDraft=null}}};
restoreButton.onclick=async()=>{if(restoreBusy||!restoreDraft||!owner()||session.user.uid!==restoreUid)return;restoreBusy=true;restoreButton.disabled=true;restoreFile.disabled=true;restorePreview.textContent='Backup save ho raha hai. Is screen ko khula rakhein…';try{await cloud.restore(restoreDraft);restoreDraft=null;restorePreview.textContent='Backup restore / save ho gaya. Khata screen par data dekhein.';notice('Backup restore / save ho gaya');render()}catch(e){restorePreview.textContent='Restore mukammal nahi hua: '+(e.message||e.code)+'. File dobara choose karne ki zaroorat nahi; masla durust karke phir Save dabayein.'}finally{restoreBusy=false;restoreFile.disabled=false;restoreButton.disabled=!restoreDraft}};

