import('./cloud.js?v=1.57.0').then(async m=>{const connected=await m.connect({reset(){if(localMode)return;resetAccountNavigation();void recoveryWriter.flush().catch(()=>{});session=null;optimistic=optimisticRecords();syncBook=null;syncKey='';syncUid='';pendingDrafts=new Map();window.ownerBackupAuthorized=false;loaded=false;records=[];unsub?.();unsub=null;document.querySelector('main').hidden=true;$('login').hidden=booting;$('dialog').close();$('printArea').innerHTML='';$('dialogBody').innerHTML='';sheetDrafts.clear();accountChoices.clear()},onSession(s){if(localMode)return;if(s.role==='owner'){try{localStorage.setItem('sam-owner-email',s.user.email)}catch{}}session=s;initSyncBook();window.ownerBackupAuthorized=s.role==='owner';if(window.ownerBackupAuthorized&&window.pendingOwnerBackup){window.pendingOwnerBackup=false;document.getElementById('emergencyBackup').click()}if(purchaseOnly()){view='purchase';selected=null}else if(view==='purchase')view='khata';$('password').value='';$('login').hidden=true;document.querySelector('main').hidden=false;$('syncStatus').textContent='Data load ho raha hai…';unsub=cloud.listen(snap=>{const before=records;records=optimistic.receive(snap.rows);const changed=before!==records;loaded=true;syncBook?.reconcile(records,snap.pendingIds||[],snap.cached,session.user.uid);for(const [id,r] of pendingDrafts)if(records.some(x=>x.id===id&&x.rev>=r.rev))pendingDrafts.delete(id);if(changed&&!purchaseOnly()&&window.KhataRecovery&&snap.rows.length)recoveryWriter.queue({format:'sam-blue-khata-v1',records:snap.rows,savedAt:new Date().toISOString(),source:'live-ledger-device-copy',importedPdfsIncluded:false,projectId:window.khataProjectId,pending:snap.pending,cached:snap.cached});$('syncStatus').textContent=(snap.pending||optimistic.pending())?'Device par saved · Cloud Sync baqi':snap.cached?'Offline / cached data':'Cloud synced';if(changed)render()},e=>{$('syncStatus').textContent='Data load nahi hua: '+e.code;if(purchaseOnly()){records=[];loaded=false;render()}error(e)});render()},onError(e,role){if(localMode)return;$('loginMessage').textContent=m.loginErrorMessage(e,role)}});window.readKhataCache=()=>connected.cachedBackup();if(localMode)return;cloud=connected;posSetup({cloud:connected,rerender:render,notice});stockSetup({cloud:connected,rerender:render,notice,owner});watchDayLock();saleSetup({cloud:connected,rerender:render,notice,owner,uid:()=>session?.user?.uid||''});const stopBooting=()=>{if(!booting)return;booting=false;if($('boot'))$('boot').hidden=true;if(!session&&document.querySelector('main').hidden)$('login').hidden=false};connected.authReady.then(stopBooting).catch(stopBooting);setTimeout(stopBooting,8000);$('loginMessage').textContent='Username admin hai. Malik ya mulazim ka password likhein.';$('loginForm').onsubmit=async e=>{e.preventDefault();if(Number(sessionStorage.getItem('sam-login-pause:'+window.khataProjectId)||0)>Date.now()){$('loginMessage').textContent='Baar baar try na karein. Thori der ruk kar dobara karein; Firebase ki pabandi ka waqt alag ho sakta hai.';return}const b=e.target.querySelector('button');b.disabled=true;try{await cloud.controller.login({role:$('role').value,username:$('username').value,password:$('password').value,ownerEmail:$('ownerEmail').value,scope:$('accessScope').value})}catch(e){$('loginMessage').textContent=m.loginErrorMessage(e,$('role').value);if(e.code==='auth/too-many-requests'){try{sessionStorage.setItem('sam-login-pause:'+window.khataProjectId,String(Date.now()+60000))}catch{}}}finally{b.disabled=false}}}).catch(e=>{booting=false;if($('boot'))$('boot').hidden=true;$('login').hidden=false;$('loginMessage').textContent='Connection load nahi hua: '+((e&&(e.code||e.message))||e)+' — yeh line Claude ko bhejein.';console.error(e)});
