function openReportPreview(heading,options={}){
 const content=$('printArea').innerHTML,uid=session?.user.uid;
 modal(options.receipt?'Receipt preview':'Report preview',`<div class="report-toolbar"><button id="downloadReport">⇩ Download PDF</button>${options.receipt?'<button id="shareReceipt" disabled>Share / WhatsApp</button>':''}</div><p id="reportDownloadStatus" role="status"></p><div class="report-preview${options.receipt?' receipt-preview':''}"><div class="report-document">${content}</div></div>`);
 const button=$('downloadReport'),status=$('reportDownloadStatus'),share=$('shareReceipt');
 const filename='Noor-Traders-'+heading.replace(/[^a-zA-Z0-9_-]/g,'-').slice(0,100)+'.pdf';
 let file=null,preparing=null;
 const valid=()=>button.isConnected&&session?.user.uid===uid&&(!options.valid||options.valid());
 const prepare=()=>{if(file)return Promise.resolve(file);if(preparing)return preparing;status.textContent='PDF tayyar ho rahi hai…';preparing=(async()=>{try{const {exportReport}=await import('./pdf-export.js');const blob=await exportReport(content);if(!valid())throw Error('Entry badal gayi ya preview band ho gaya. Receipt dobara kholein.');file=new File([blob],filename,{type:'application/pdf'});if(share)share.disabled=false;status.textContent='PDF tayyar hai. Download ya Share karein.';return file}finally{preparing=null}})();return preparing};
 button.onclick=async()=>{button.disabled=true;try{const ready=await prepare();if(!valid())throw Error('Entry badal gayi. Receipt dobara kholein.');download(filename,ready);status.textContent='PDF download bhej di gayi hai.'}catch(e){status.textContent=e.message||'PDF nahi bani. Dobara koshish karein.'}finally{button.disabled=false}};
 if(share){share.onclick=async()=>{if(!file||!valid()){status.textContent='Entry badal gayi. Receipt dobara kholein.';return}share.disabled=true;try{if(navigator.share&&navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Noor Traders receipt'});status.textContent='Share window band ho gayi.'}else{download(filename,file);status.textContent='PDF download kar di. WhatsApp mein document attach kar dein.'}}catch(e){if(e.name!=='AbortError')status.textContent='Share nahi hua. Download PDF karke WhatsApp mein attach karein.'}finally{share.disabled=false}};prepare().catch(e=>{if(button.isConnected)status.textContent=e.message||'PDF nahi bani. Download PDF se dobara koshish karein.'})}
}


